files.content:
*,
*::before,
*::after {
  box-sizing: border-box;
}

body {
  display: grid;
  place-items: center;
  min-block-size: 100dvb;
  margin: 0;
  padding: 2em;
  font-family: 'Open Sans', sans-serif;
  font-size: 18px;
  background-color: #fff;
  background-image: url(https://code.s3.yandex.net/web-code/images/dotted.svg);
}

.card {
  position: relative;
  border: 1px solid #000;
  padding: 1em;
  background-color: #fff;
}

.card__controls {
  position: absolute;
  display: flex;
  gap: 0.5em;
  margin: 0;
  padding: 0;
  list-style: none;
  inset-block-start: 0.5em;
  inset-inline-end: 0.5em;
}

.card__title {
  margin: 0;
  font-size: 2em;
  text-transform: uppercase;
}

.card__controls button {
  inline-size: 40px;
  block-size: 40px;
  border: 1px solid #000;
  padding: 0.5em;
  background-color: #fff;
  cursor: pointer;
}

.card__controls button:hover {
  border: 1px solid #6dc1fd;
}

.card__controls button:focus-visible {
  border: 1px solid #6dc1fd;
}

.card__controls svg {
  inline-size: 100%;
  block-size: 100%;
  object-fit: contain;
}

.card__controls button:hover svg {
  fill: #6dc1fd;
}

.card__controls button:focus-visible svg {
  fill: #6dc1fd;
}
